class LinearRegressionNet(nn.Module):
    def __init__(self, in_features):
        super().__init__()
        self.fc1 = nn.Linear(in_features, 16)   # fully connected layer 1
        self.fc2 = nn.Linear(16, 1)             # fully connected layer 2 (output)

    def forward(self, x):
        x = self.fc1(x)
        x = self.fc2(x)
        return x

